import React, { useState, useEffect } from 'react';
import { collection, query, orderBy, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from './firebase';
import {
  Container,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Box,
  Button,
} from '@mui/material';

function AdminPanel() {
  const [requests, setRequests] = useState([]);
  const [updating, setUpdating] = useState(false);

  useEffect(() => {
    // Create a query against the requests collection
    const q = query(collection(db, 'requests'), orderBy('timestamp', 'desc'));

    // Set up real-time listener
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const requestsData = [];
      querySnapshot.forEach((doc) => {
        requestsData.push({
          id: doc.id,
          ...doc.data(),
          timestamp: doc.data().timestamp?.toDate().toLocaleString() || 'N/A'
        });
      });
      setRequests(requestsData);
    });

    // Cleanup subscription
    return () => unsubscribe();
  }, []);

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Typography variant="h4" gutterBottom>
        Feature Requests Admin Panel
      </Typography>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Type</TableCell>
              <TableCell>Description</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Timestamp</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {requests.map((request) => (
              <TableRow key={request.id}>
                <TableCell>
                  <Chip 
                    label={request.type} 
                    color={request.type === 'formula' ? 'primary' : 'secondary'}
                  />
                </TableCell>
                <TableCell>{request.description}</TableCell>
                <TableCell>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Chip 
                      label={request.status}
                      color={
                        request.status === 'pending' ? 'warning' :
                        request.status === 'completed' ? 'success' : 
                        request.status === 'in_progress' ? 'info' : 'default'
                      }
                    />
                    {request.status !== 'completed' && (
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={async () => {
                          setUpdating(true);
                          try {
                            const newStatus = request.status === 'pending' ? 'in_progress' : 'completed';
                            await updateDoc(doc(db, 'requests', request.id), {
                              status: newStatus,
                              updatedAt: new Date()
                            });
                          } catch (error) {
                            console.error('Error updating status:', error);
                          }
                          setUpdating(false);
                        }}
                        disabled={updating}
                      >
                        {request.status === 'pending' ? 'Start' : 'Complete'}
                      </Button>
                    )}
                  </Box>
                </TableCell>
                <TableCell>{request.timestamp}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Container>
  );
}

export default AdminPanel;
